function t(key, vars) {
  let s = (DICT[LANG] && DICT[LANG][key]);
  if (s == null) s = DICT.ru[key];
  if (s == null) return key;
  if (vars) for (const k in vars) s = String(s).split("{" + k + "}").join(vars[k]);
  return s;
}
function tn(key, n) {
  const f = (DICT[LANG] && DICT[LANG][key]) || DICT.ru[key];
  let w;
  if (LANG === "uz") w = f[0];
  else if (LANG === "en") w = n === 1 ? f[0] : f[1];
  else { const a = Math.abs(n) % 100, b = a % 10; w = f[a > 10 && a < 20 ? 2 : b > 1 && b < 5 ? 1 : b === 1 ? 0 : 2]; }
  return w;
}
function rubricName(ru) { return LANG === "ru" ? ru : (RUBRIC_I18N[ru]?.[LANG]?.[0] || ru); }
function rubricDesc(ru, descRu) { return LANG === "ru" ? descRu : (RUBRIC_I18N[ru]?.[LANG]?.[1] || descRu); }
function setLang(l) { try { localStorage.setItem("lawart-lang", l); } catch (e) { } const u = new URL(location.href); u.searchParams.delete("lang"); location.href = u.toString(); }
function applyI18n(root = document) {
  root.querySelectorAll("[data-t]").forEach(el => { el.innerHTML = t(el.dataset.t); });
  root.querySelectorAll("[data-tp]").forEach(el => { el.setAttribute("placeholder", t(el.dataset.tp)); });
  root.querySelectorAll("[data-ta]").forEach(el => { el.setAttribute("aria-label", t(el.dataset.ta)); });
}
